// Package output compares generated files with the output directory and writes them.
package output

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

// Marker is the first line of every generated file.
const Marker = "<!-- Code generated by docgen. DO NOT EDIT. -->"

// File is one generated file.
type File struct {
	Path    string // slash path relative to the output directory
	Content []byte // complete file content, starting with Marker
}

// Plan lists the changes needed to bring the output directory up to date.
type Plan struct {
	Write  []string // sorted; files missing on disk or with different content
	Delete []string // sorted; generated files on disk that are no longer produced
}

// Paths returns Write and Delete merged and sorted.
func (p *Plan) Paths() []string {
	paths := make([]string, 0, len(p.Write)+len(p.Delete))
	paths = append(paths, p.Write...)
	paths = append(paths, p.Delete...)
	slices.Sort(paths)
	return paths
}

// hasMarker reports whether data's first line (up to the first '\n') equals Marker.
func hasMarker(data []byte) bool {
	line, _, _ := bytes.Cut(data, []byte("\n"))
	return string(line) == Marker
}

// Diff compares files with the contents of outDir. outDir may not exist.
func Diff(outDir string, files []File) (*Plan, error) {
	plan := &Plan{}
	produced := make(map[string]struct{}, len(files))
	for _, f := range files {
		produced[f.Path] = struct{}{}
		target := filepath.Join(outDir, filepath.FromSlash(f.Path))
		data, err := os.ReadFile(target)
		if errors.Is(err, fs.ErrNotExist) {
			plan.Write = append(plan.Write, f.Path)
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read %s: %w", target, err)
		}
		if !hasMarker(data) {
			return nil, fmt.Errorf("refusing to overwrite %s: not generated by docgen", target)
		}
		if !bytes.Equal(data, f.Content) {
			plan.Write = append(plan.Write, f.Path)
		}
	}

	err := filepath.WalkDir(outDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			if path == outDir && errors.Is(err, fs.ErrNotExist) {
				return nil
			}
			return err
		}
		if !d.Type().IsRegular() || !strings.HasSuffix(d.Name(), ".md") {
			return nil
		}
		rel, err := filepath.Rel(outDir, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if _, ok := produced[rel]; ok {
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		if hasMarker(data) {
			plan.Delete = append(plan.Delete, rel)
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("walk %s: %w", outDir, err)
	}

	slices.Sort(plan.Write)
	slices.Sort(plan.Delete)
	return plan, nil
}

// Apply executes plan. It writes only the files listed in plan.Write.
func Apply(outDir string, files []File, plan *Plan) error {
	byPath := make(map[string]File, len(files))
	for _, f := range files {
		byPath[f.Path] = f
	}
	for _, p := range plan.Write {
		f, ok := byPath[p]
		if !ok {
			return fmt.Errorf("plan lists %s, which is not a generated file", p)
		}
		if err := writeFile(filepath.Join(outDir, filepath.FromSlash(p)), f.Content); err != nil {
			return err
		}
	}
	for _, p := range plan.Delete {
		target := filepath.Join(outDir, filepath.FromSlash(p))
		if err := os.Remove(target); err != nil {
			return fmt.Errorf("remove %s: %w", target, err)
		}
		if err := removeEmptyParents(outDir, filepath.Dir(target)); err != nil {
			return err
		}
	}
	return nil
}

func writeFile(target string, content []byte) error {
	dir := filepath.Dir(target)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("create %s: %w", dir, err)
	}
	tmp, err := os.CreateTemp(dir, ".docgen-*")
	if err != nil {
		return fmt.Errorf("write %s: %w", target, err)
	}
	renamed := false
	defer func() {
		if !renamed {
			os.Remove(tmp.Name())
		}
	}()
	if _, err := tmp.Write(content); err != nil {
		tmp.Close()
		return fmt.Errorf("write %s: %w", target, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("write %s: %w", target, err)
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", target, err)
	}
	if err := os.Rename(tmp.Name(), target); err != nil {
		return fmt.Errorf("write %s: %w", target, err)
	}
	renamed = true
	return nil
}

// removeEmptyParents removes dir and its parents while they are empty, stopping at outDir.
func removeEmptyParents(outDir, dir string) error {
	for dir != outDir && strings.HasPrefix(dir, outDir+string(filepath.Separator)) {
		entries, err := os.ReadDir(dir)
		if err != nil {
			return fmt.Errorf("read %s: %w", dir, err)
		}
		if len(entries) > 0 {
			return nil
		}
		if err := os.Remove(dir); err != nil {
			return fmt.Errorf("remove %s: %w", dir, err)
		}
		dir = filepath.Dir(dir)
	}
	return nil
}
